p.update(id='yamaha-2026-yz450f-us-rear-caliper-rebuild-v1',title='Rebuild the stock rear brake caliper',affected_components=['rear_brake','brakes','rear_wheel','wheels','swingarm','chain'],completeness='Complete rear-caliper seal/piston service with rear-wheel access, chain adjustment, bleeding and refit. Serviceable master cylinder, hose, disc and wheel required.',entry_state=['Assembled exact US2026 stock YZ450F with serviceable rear master cylinder, hose, disc and wheel.','Correct rear caliper seals and any needed piston/pad assemblies available.'],exit_state=['Rear caliper rebuilt; wheel, chain, pad hardware and hose restored.','Rear circuit bled and closed; leak, pedal and brake-effect checks passed.'])
p['applicability']['included']='Stock rear brake on exact US2026 YZ450F';p['required_tools'][0]['size']='1.5–135 Nm; include rear axle tooling';p['required_parts'][1]=dict(name='One piston seal and one dust seal',purpose='Mandatory rear caliper renewals');p['required_parts'][2]['purpose']='Rear caliper hose connection';p['required_parts'][-1]=dict(name='Replacement piston and paired rear pad assemblies if required',purpose='Match exact stock rear caliper');p['required_parts'].append(dict(name='Lithium-soap-based grease',purpose='Rear wheel seal lips and axle as illustrated'))
rows=[
('prepare','Prepare rear circuit','Secure bike upright with rear wheel raised; select neutral. Keep rear reservoir top horizontal. Remove reservoir cap, diaphragm plate and diaphragm; protect surfaces from fluid.',[108,110,134,153],'Bike stable; only rear circuit opened.',False),
('drain','Drain the rear brake','Remove caliper protector and hose union bolt with both copper washers. Place hose end in a catch container and pump out fluid before disassembling caliper. Discard old fluid and washers.',[150,157],'Circuit drained; do not operate pedal once wheel/pads are out.',False),
('wheel-remove','Remove rear wheel',wheel['steps'][1]['instruction'].replace(' without disturbing the hydraulic line',''),[134,136],'Wheel and disc protected; collars/pullers retained by side.',False),
('strip','Strip caliper and pads','Remove plug, pin and both pad assemblies. Separate caliper/bracket and retain both pad springs in diagram150 positions. Contain piston with a rag and expel using air through hose port; never pry. Remove old seals and bleeder.',[150,151,157],'Piston contained; body/bore undamaged.',False),
('inspect','Inspect components','Replace rusted/scratched/worn piston; replace scratched/worn cylinder or cracked/damaged caliper body. Replace damaged bracket. Clear blocked passages with air. Inspect wheel, axle, collars and bearings before refitting.',[131,136,157],'Record defects; proceed only with serviceable or correctly replaced parts.',True),
('seals','Renew seals and piston','Clean internals with fresh DOT4, never solvent. Fit new piston and dust seals in diagram151 grooves using silicone grease at S marks. Lubricate piston with DOT4 and insert; install bleeder5 Nm.',[7,151,157,158],'Piston seal inward of dust seal; both seated without damage.',False),
('pads','Restore bracket and pads','Apply silicone grease to diagram150 sliding-pin locations. Reunite bracket/caliper. Restore both springs and complete pad assemblies as illustrated; replace pads as a set at1.0 mm lining limit. Engage pad projections in recesses and insert pin temporarily.',[7,150,156],'Record pad assessment; spring/backing-part positions match diagram.',True),
('wheel-refit','Refit rear wheel',wheel['steps'][3]['instruction'],[134,137,138],'Bracket correctly engaged in swingarm guide; disc between pads.',False),
('wheel-hardware','Install axle hardware',wheel['steps'][4]['instruction'],[138],'Both pullers and collars in correct positions.',False),
('chain','Adjust drive chain',wheel['steps'][5]['instruction'],[111,138],'Record slack and even alignment at source measurement location.',True),
('axle','Secure rear axle',wheel['steps'][6]['instruction'],[112,138],'Record135 Nm axle and21 Nm locknuts; slack rechecked.',True),
('hose','Connect brake hose','Fit two new copper washers and hose; match diagram158 pipe-bend orientation and contact with caliper projection. Tighten union bolt30 Nm. Tighten pad pin17 Nm, plug2.5 Nm and protector bolts7 Nm.',[150,156,158],'Record new washers, hose orientation and torques.',True),
('fill','Fill for bleeding','Fill horizontal reservoir to specified level with fresh DOT4 and fit diaphragm. Secure clear hose to bleeder and lead to catch container. Prevent water entry, overflow and reservoir running dry.',[108,109,110,158],'Correct fluid; sufficient supply throughout bleeding.',False),
('bleed','Bleed rear circuit','Slowly pump pedal several times, then press fully and hold. Open bleeder; close before releasing pedal. Repeat until hose fluid is bubble-free, replenishing reservoir. If tiny bubbles persist, let fluid settle a few hours and repeat.',[110,111],'Record bubble-free fluid and firm pedal.',True),
('close','Close reservoir','Tighten bleeder5 Nm and refit cap. Restore reservoir level upright/horizontal. Refit diaphragm, plate and cap in diagram153 order; cap screws1.5 Nm. Clean all spills.',[108,109,111,151,153],'Record final fluid level and closure torques.',True),
('verify','Check wheel and brake','Turn rear wheel; check chain tracking and correct disc position. Apply rear brake repeatedly; inspect hose/connections for leaks. A soft pedal needs further bleeding. After stationary checks pass, check brake effect on a dry test surface.',[90,110,138,158],'Record no leaks, firm pedal and proper brake effect; lower supported bike before riding.',True),
]
